var _markdown = "\n\n`vc` · 扩展 `CLEO` · 需 CLEO\n\n写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 加载动态库 [#加载动态库]\n\n<Opcode id=\"0AA2\" name=\"LOAD_DYNAMIC_LIBRARY\" member=\"DynamicLibrary.Load\">\n  把 DLL/模块加载进游戏进程。成功条件为真。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AA2 LOAD_DYNAMIC_LIBRARY\n      in: fileName\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local mod = loadDynamicLibrary(\"kernel32.dll\")\n      if mod then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = DynamicLibrary.load(fileName)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 卸载动态库 [#卸载动态库]\n\n<Opcode id=\"0AA3\" name=\"FREE_DYNAMIC_LIBRARY\" member=\"DynamicLibrary.Free\">\n  卸载模块。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AA3 FREE_DYNAMIC_LIBRARY\n      in: self\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      freeDynamicLibrary(mod)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      DynamicLibrary.free(self)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 取导出过程地址 [#取导出过程地址]\n\n<Opcode id=\"0AA4\" name=\"GET_DYNAMIC_LIBRARY_PROCEDURE\" member=\"DynamicLibrary.GetProcedure\">\n  取导出地址。条件表示是否找到。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AA4 GET_DYNAMIC_LIBRARY_PROCEDURE\n      in: procName, self\n      out: address\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local addr = getDynamicLibraryProcedure(\"GetTickCount\", mod)\n      if addr then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const address = DynamicLibrary.getProcedure(procName, self)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
